  isMastered: (m) => !!m && m.n >= 2 && m.theta >= 3.5,
  reviewDue: () => false,
  bossDue: (s: EngineState) => new Set(s.conceptsSinceBoss).size >= 3,
  bossOutcome: (hits, max) => (hits === max ? "flawless" : hits * 2 >= max ? "victory" : "retreat"),
