// Temporary live sanity check (not committed). Loads .env.local without printing it.
import { readFileSync } from "node:fs";
import { it } from "vitest";
import type { LearningMomentInput } from "@/lib/contracts/moment";

for (const line of readFileSync(new URL("../.env.local", import.meta.url), "utf8").split("\n")) {
  const m = line.match(/^\s*([A-Z0-9_]+)\s*=\s*(.*)\s*$/);
  if (m && !process.env[m[1]]) process.env[m[1]] = m[2].replace(/^["']|["']$/g, "");
}

const moment: LearningMomentInput = {
  type: "spot_issue",
  concept: "data leakage",
  question:
    "Here are the columns: customer_id, tenure_months, contract_type, monthly_charges, total_charges, support_tickets_90d, payment_method, cancellation_request_date. One of these would make the model look amazing but fail in production. Which one, and why?",
  ideal_answer: "cancellation_request_date: it is only filled in after a customer has decided to leave, so it leaks the label and won't be available when predicting future churn.",
  rubric: {
    key_points: ["cancellation_request_date", "only known after the churn decision / leaks the target"],
    acceptable_variants: ["the cancellation date column"],
    misconceptions: ["customer_id leaks the label", "total_charges is a leak"],
  },
  mc_fallback: {
    options: ["customer_id", "cancellation_request_date", "tenure_months", "support_tickets_90d"],
    correct_index: 1,
    why: [
      "IDs are arbitrary labels; they don't encode churn.",
      "It's recorded only after a customer decides to leave, so it leaks the answer.",
      "Tenure is known before churn and is a legitimate signal.",
      "Recent tickets are known beforehand and are a legitimate signal.",
    ],
  },
  difficulty: 2,
  first_exposure: true,
  learning_value: 5,
  value_reason: "A leak would make their model useless",
  costly_mistake: true,
  timing: "after_step",
};

const intent = { goal: "Help me train a model to predict customer churn from this CSV", familiarity: "new" as const, minutes: 10, demo: true };
const show = (label: string, v: unknown) => console.log(`\n=== ${label} ===\n${JSON.stringify(v, null, 2)}`);

it("live content checks", { timeout: 600_000 }, async () => {
  const { content } = await import("@/lib/claude/content");
  const timed = async <T,>(label: string, p: Promise<T>) => {
    const t = Date.now();
    try {
      const v = await p;
      show(`${label} (${Date.now() - t} ms)`, v);
      return v;
    } catch (e) {
      show(`${label} FAILED (${Date.now() - t} ms)`, e instanceof Error ? `${e.name}: ${e.message}` : String(e));
      return null;
