  mc_fallback: {
    options: ["customer_id", "cancellation_request_date", "tenure_months", "support_tickets_90d"],
    correct_index: 1,
    why: [
      "IDs are arbitrary labels; they don't encode churn.",
      "It's recorded only after a customer decides to leave, so it leaks the answer.",
      "Tenure is known before churn and is a legitimate signal.",
      "Recent tickets are known beforehand and are a legitimate signal.",
    ],
  },
  difficulty: 2,
  first_exposure: true,
  learning_value: 5,
  value_reason: "A leak would make their model useless",
  costly_mistake: true,
  timing: "after_step",
};

